'use strict';
// ===================== Academic Intelligence views =====================
const IV = { tab: 'overview', cid: null, risk: 'all', riskCls: '' };
const INTEL_TABS = [['overview', 'Overview', 'gauge'], ['risks', 'Risks', 'triangle-alert'], ['sim', 'Grade simulator', 'sliders-horizontal'], ['director', 'Study Director', 'target'], ['mastery', 'Topic mastery', 'layout-grid'], ['workload', 'Workload', 'calendar-clock'], ['reports', 'Reports', 'file-text'], ['goals', 'Goals', 'flag']];
const tagEst = '<span class="tag-obs a" title="Calculated from your data, not an actual grade">Estimate</span>';
const tagMeas = '<span class="tag-obs o" title="Directly from your records">Measured</span>';
const scoreColor = (v) => (v == null ? 'var(--dim)' : v >= 0.85 ? 'var(--good)' : v >= 0.65 ? 'var(--accent)' : v >= 0.5 ? 'var(--warn)' : 'var(--bad)');
function segRing(comps, center, sub, size = 200) {
  const r = 82, sw = 15, C = 2 * Math.PI * r, W = sum(comps.map((c) => c.w)) || 1, gap = 5; let off = 0, g = '';
  for (const c of comps) { const L = (c.w / W) * C - gap; g += `<circle cx="100" cy="100" r="${r}" fill="none" stroke="var(--raised-2)" stroke-width="${sw}" stroke-dasharray="${L} ${C}" stroke-dashoffset="${-off}" transform="rotate(-90 100 100)"/><circle cx="100" cy="100" r="${r}" fill="none" stroke="${scoreColor(c.v)}" stroke-width="${sw}" stroke-dasharray="${Math.max(0.01, L * c.v)} ${C}" stroke-dashoffset="${-off}" transform="rotate(-90 100 100)" data-tip="${esc(`<b>${esc(c.k)}</b> · ${Math.round(c.v * 100)}/100 · weight ${c.w}%<br>${esc(c.how)}`)}" style="transition:stroke-dasharray .8s ease"/>`; off += L + gap; }
  return `<div class="ring" style="width:${size}px;height:${size}px"><svg viewBox="0 0 200 200" width="${size}" height="${size}" style="transform:none">${g}</svg><div class="rv"><b style="font-size:${size / 4.2}px">${center}</b><small>${sub}</small></div></div>`;
}
function stackBars(cols, o = {}) {
  const tot = cols.map((c) => sum(c.parts.map((p) => p.v)));
  if (!tot.some(Boolean)) return emptyChart(o.empty || 'Nothing scheduled');
  const W = 640, H = o.h || 210, L = 34, R = 8, T = 14, B = 26, n = cols.length, slot = (W - L - R) / n, bw = Math.min(34, slot * 0.62);
  const max = Math.max(o.cap || 0, ...tot) * 1.12 || 1, y = (v) => T + (H - T - B) * (1 - v / max); let g = '';
  for (let k = 0; k <= 3; k++) { const v = (max * k) / 3; g += `<line class="gl" x1="${L}" x2="${W - R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L - 6}" y="${y(v) + 3.5}" text-anchor="end">${o.fmtAxis ? o.fmtAxis(v) : Math.round(v)}</text>`; }
  if (o.cap) g += `<line x1="${L}" x2="${W - R}" y1="${y(o.cap)}" y2="${y(o.cap)}" stroke="var(--warn)" stroke-dasharray="5 5" stroke-width="1.5"/><text x="${W - R}" y="${y(o.cap) - 5}" text-anchor="end" style="fill:var(--warn)">${esc(o.capLabel || 'capacity')}</text>`;
  cols.forEach((c, i) => { const cx = L + slot * i + slot / 2; let base = 0; for (const p of c.parts) { if (!p.v) continue; const y1 = y(base + p.v), y0 = y(base); g += `<rect x="${cx - bw / 2}" y="${y1}" width="${bw}" height="${Math.max(1, y0 - y1 - 1)}" rx="3" fill="${p.color}" data-tip="${esc(`<b>${esc(c.label)}</b><br>${esc(p.name)}: ${o.fmt ? o.fmt(p.v) : p.v}`)}"/>`; base += p.v; }
    if (c.mark) g += `<circle cx="${cx}" cy="${T - 4}" r="4" fill="var(--bad)" data-tip="${esc(c.mark)}"/>`;
    g += `<text x="${cx}" y="${H - 8}" text-anchor="middle" style="${c.today ? 'fill:var(--accent);font-weight:700' : ''}">${esc(c.short)}</text>`; });
  return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(o.aria || 'Stacked bar chart')}">${g}</svg></div>`;
}
/** Horizontal rows: a dot for one value, a ring for another, joined by a line (current vs goal, start vs end). */
function dumbbell(rows, o = {}) {
  if (!rows.length) return emptyChart(o.empty || 'No data');
  const lo = Math.max(0, Math.floor(Math.min(...rows.flatMap((r) => [r.a, r.b]).filter((v) => v != null)) / 5) * 5 - 5), hi = Math.min(110, Math.ceil(Math.max(...rows.flatMap((r) => [r.a, r.b]).filter((v) => v != null)) / 5) * 5 + 5);
  const W = 640, rowH = 34, L = 150, R = 50, H = rows.length * rowH + 24, x = (v) => L + ((v - lo) / (hi - lo || 1)) * (W - L - R); let g = '';
  for (let k = 0; k <= 4; k++) { const v = lo + ((hi - lo) * k) / 4; g += `<line class="gl" x1="${x(v)}" x2="${x(v)}" y1="4" y2="${H - 20}"/><text x="${x(v)}" y="${H - 6}" text-anchor="middle">${Math.round(v)}</text>`; }
  rows.forEach((r, i) => { const cy = 18 + i * rowH; g += `<text x="${L - 10}" y="${cy + 4}" text-anchor="end" style="fill:var(--fg-2);font-weight:600;font-size:12px">${esc(r.label.length > 20 ? r.label.slice(0, 19) + '…' : r.label)}</text>`;
    if (r.a != null && r.b != null) g += `<line x1="${x(r.a)}" x2="${x(r.b)}" y1="${cy}" y2="${cy}" stroke="${r.b >= r.a ? 'var(--good)' : 'var(--bad)'}" stroke-width="4" stroke-linecap="round" opacity=".55"/>`;
    if (r.b != null) g += `<circle cx="${x(r.b)}" cy="${cy}" r="7" fill="none" stroke="var(--fg-2)" stroke-width="2" data-tip="${esc(`${esc(r.label)} · ${o.bLabel || 'target'}: ${round(r.b, 1)}`)}"/>`;
    if (r.a != null) g += `<circle cx="${x(r.a)}" cy="${cy}" r="7" fill="${r.color || 'var(--accent)'}" data-tip="${esc(`${esc(r.label)} · ${o.aLabel || 'now'}: ${round(r.a, 1)}`)}"/><text x="${W - R + 8}" y="${cy + 4}" style="fill:${r.b == null ? 'var(--fg-2)' : r.a >= r.b ? 'var(--good)' : 'var(--bad)'};font-weight:700">${r.b == null ? round(r.a, 1) : (r.a >= r.b ? '+' : '') + round(r.a - r.b, 1)}</text>`; });
  return `<div class="chart" style="max-width:${Math.max(560, 720)}px"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(o.aria || 'Comparison')}">${g}</svg></div><div class="legend"><span><i class="dot-c"></i>${esc(o.aLabel || 'now')}</span><span><i class="dot-c" style="background:none;border:2px solid var(--fg-2)"></i>${esc(o.bLabel || 'target')}</span></div>`;
}
const lvlPill = (l) => `<span class="badge" style="background:color-mix(in srgb, ${LVL[l][2]} 18%, transparent);color:${LVL[l][2]}">${LVL[l][1]}</span>`;
const clsChip = (cid) => (cid ? `<span class="row tiny muted" style="gap:5px"><i class="dot-c" style="--c:${clsColor(cid)};width:7px;height:7px"></i>${esc(clsName(cid))}</span>` : '');
function classChips(id, sel, allLabel) { return `<div class="chips" id="${id}">${allLabel ? `<button class="chip${!sel ? ' on' : ''}" data-c="">${allLabel}</button>` : ''}${S.classes.map((c) => `<button class="chip${sel === c.id ? ' on' : ''}" data-c="${c.id}"><i class="dot-c" style="--c:${c.color}"></i>${esc(c.name)}</button>`).join('')}</div>`; }

VIEWS.intel = (rt) => {
  if (INTEL_TABS.some(([k]) => k === rt.arg)) IV.tab = rt.arg;
  if (rt.sub && cls(rt.sub)) IV.cid = rt.sub;
  if (!IV.cid || !cls(IV.cid)) IV.cid = S.classes[0]?.id || null;
  ensureTopics(); takeSnapshot(); checkGoals();
  const empty = !S.classes.length;
  const v = empty ? { html: `<div class="card">${emptyState('gauge', 'Nothing to analyze yet', 'Academic Intelligence works from your classes, grades, assignments and study history. Add a class or load the sample semester from the Home page.', `<button class="btn primary" onclick="editClass()">${icon('plus', 15)} Add class</button>`)}</div>` }
    : ({ overview: intelOverview, risks: intelRisks, sim: intelSim, director: intelDirector, mastery: intelMastery, workload: intelWorkload, reports: intelReports, goals: intelGoals }[IV.tab])();
  return { title: 'Academic Intelligence', sub: v.sub || 'Where you stand, what’s holding you back, and what to do next', actions: v.actions || '',
    html: `<div class="tabs" id="iv-tabs">${INTEL_TABS.map(([k, l, ic]) => `<button class="${IV.tab === k ? 'on' : ''}" data-t="${k}">${icon(ic, 15)}${l}${k === 'risks' && !empty ? (() => { const n = risks().filter((r) => r.level === 'high').length; return n ? ` <span class="badge bad">${n}</span>` : ''; })() : ''}</button>`).join('')}</div>${v.html}`,
    mount(root) { $('#iv-tabs', root).onclick = (e) => { const b = e.target.closest('[data-t]'); if (b) go('intel', b.dataset.t); }; root.addEventListener('click', (e) => { const g = e.target.closest('[data-go]'); if (g) { e.preventDefault(); go(...JSON.parse(g.dataset.go)); } }); v.mount?.(root); } };
};
const goBtn = (arr, label = 'Open') => `<button class="btn sm" data-go='${esc(JSON.stringify(arr))}'>${esc(label)} ${icon('arrow-right', 13)}</button>`;

// ---------- overview ----------
function statusLines() {
  const ps = performanceScore(), good = [], bad = [];
  for (const c of ps.comps) { if (c.v >= 0.85) good.push(`${c.k} ${Math.round(c.v * 100)}/100: ${c.how.split(';')[0].replace(/\.$/, '')}.`); else if (c.v < 0.65) bad.push(`${c.k} ${Math.round(c.v * 100)}/100: ${c.how.split(';')[0].replace(/\.$/, '')}.`); }
  for (const c of S.classes) { const g = classGrade(c.id).pct, tr = gradeTrend(c.id); if (g != null && c.goal && g >= c.goal) good.push(`${c.name} is at ${round(g, 1)}%, at or above your ${c.goal}% goal.`); if (tr && tr.perWeek >= 0.5) good.push(`${c.name} is rising ${round(tr.perWeek, 1)} pts/week.`); }
  const mast = S.topics.map(topicMastery).filter((m) => m.status === 'mastered'); if (mast.length) good.push(`${mast.length} topic${mast.length === 1 ? '' : 's'} mastered: ${mast.slice(0, 3).map((m) => m.t.name).join(', ')}.`);
  const rk = risks(); for (const r of rk.filter((r) => r.level === 'high').slice(0, 3).reverse()) bad.unshift(`${r.title}.`);
  return { ps, good: good.slice(0, 4), bad: [...new Set(bad)].slice(0, 4), rk };
}
function todayActions() {
  const out = [], rk = risks(), dr = directorRecs().filter((r) => r.status === 'open' || r.status === 'accepted');
  for (const r of rk.filter((r) => r.level === 'high').slice(0, 3)) out.push({ text: r.action, why: r.title, lvl: 'high', go: r.go });
  for (const r of dr.slice(0, 4)) if (!out.some((o) => o.text.includes(r.topic))) out.push({ text: `${r.kind === 'assignment' ? 'Work on' : 'Study'} ${r.topic} (${fmtMins(r.mins)}). ${METHODS[r.method]}.`, why: r.reason, lvl: r.priority === 'High' ? 'medium' : 'low', go: ['intel', 'director'] });
  return out.slice(0, 5);
}
function intelOverview() {
  const { ps, good, bad, rk } = statusLines(), g = gpaFor(), pg = projectedGPA(), acts = todayActions(), t = today();
  const cs = completionStats(addDays(t, -30), addDays(t, -1)), ot = onTimeStats(addDays(t, -60), t), con = consistency(), q = quizStats(addDays(t, -30), t);
  const gd = [...new Set(S.classes.flatMap((c) => gradedItems(c.id).map((x) => x.date)))].sort().slice(-14);
  const gs = gd.map((d) => { const x = gpaFor(undefined, d); return x ? round(x.unweighted, 2) : null; });
  const ranks = S.classes.map((c) => ({ c, g: classGrade(c.id).pct, tr: gradeTrend(c.id), p: projectedGrade(c.id), h: gradeHistory(c.id).slice(-10).map((x) => x.pct) }));
  const ms = S.topics.map(topicMastery).filter((m) => m.score != null).sort((a, b) => b.score - a.score);
  const typeAvg = {}; for (const c of S.classes) for (const x of gradedItems(c.id)) { const ty = x.kind === 'exam' ? 'test' : byId('assignments', x.id)?.type || 'other'; (typeAvg[ty] ||= []).push((x.score / x.max) * 100); }
  const ta = Object.entries(typeAvg).filter(([, v]) => v.length >= 2).map(([k, v]) => ({ k, v: avg(v), n: v.length })).sort((a, b) => b.v - a.v);
  return { sub: `Score built from ${ps.comps.length} measured area${ps.comps.length === 1 ? '' : 's'} · updated ${new Date().toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}`,
    html: `<div class="intel-hero">
      <div class="ih-score">${ps.score == null ? ring(0, '—', 'no data', 200) : segRing(ps.comps, ps.score, ps.label, 200)}<div class="tiny muted" style="text-align:center;max-width:220px">Academic performance score · ${ps.comps.length ? `${Math.round(ps.coverage * 100)}% of weights have data` : 'needs grades or activity'}</div></div>
      <div class="ih-status">
        <div class="ih-col good"><div class="eyebrow">${icon('trending-up', 13)} Going well</div>${good.length ? good.map((x) => `<p>${esc(x)}</p>`).join('') : '<p class="muted">Not enough data yet to call anything a strength.</p>'}</div>
        <div class="ih-col warn"><div class="eyebrow">${icon('triangle-alert', 13)} Needs attention</div>${bad.length ? bad.map((x) => `<p>${esc(x)}</p>`).join('') : '<p class="muted">Nothing is flagged right now.</p>'}</div>
        <div class="ih-col acc"><div class="eyebrow">${icon('target', 13)} Priority</div>${acts[0] ? `<p><b>${esc(acts[0].text)}</b></p><p class="muted small">${esc(acts[0].why)}</p>` : '<p class="muted">No urgent actions.</p>'}</div>
      </div>
      <div class="ih-gpa"><div class="tiny muted">GPA ${tagMeas}</div><b class="num">${g ? g.unweighted.toFixed(2) : '—'}</b><div class="tiny muted">${g ? g.weighted.toFixed(2) + ' weighted' : 'no grades yet'}</div>
        <div style="height:1px;background:var(--line);margin:10px 0"></div><div class="tiny muted">Projected ${tagEst}</div><b class="num" style="color:var(--accent)">${pg ? pg.unweighted.toFixed(2) : '—'}</b><div class="tiny muted">${pg ? `${pg.basis} class${pg.basis === 1 ? '' : 'es'} with 3+ grades projected; remaining work at your recent scores (last 3 per category)` : 'needs 3+ graded items in a class'}</div></div>
    </div>
    <div class="kpis">${[['Completion', cs.rate, cs.n ? `${cs.done}/${cs.n} due in last 30 days` : 'no past-due work yet'], ['On time', ot.rate, ot.n ? `${ot.ot}/${ot.n} finished in last 60 days` : 'finish work to measure'], ['Consistency', S.sessions.length ? con.rate : null, `${con.n} of 28 days with 10+ min`], ['Quiz accuracy', q.acc, q.n ? `${q.n} quiz/test${q.n === 1 ? '' : 's'}, 30 days` : 'no quizzes in 30 days']].map(([l, v, s]) => `<div class="kpi" style="display:flex;gap:12px;align-items:center">${ring((v ?? 0) * 100, v == null ? '—' : Math.round(v * 100) + '%', '', 64, scoreColor(v), 7)}<div><div class="k-l">${l}</div><div class="k-s">${s}</div></div></div>`).join('')}</div>
    <div class="grid g-12">
      <div class="card s-7"><div class="card-h"><h2>Grade trajectory</h2><span class="end tiny muted">slope = points per week, last 45 days</span></div>
        <div class="traj">${ranks.map((r) => `<a class="traj-row" href="#classes/${r.c.id}/analytics"><span class="row" style="gap:8px;min-width:0"><i class="dot-c" style="--c:${r.c.color}"></i><b class="grow" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(r.c.name)}</b></span>${spark(r.h, r.c.color, 110, 30) || '<span class="tiny dim">too few grades</span>'}<span class="num"><b style="color:${gradeColor(r.g)}">${r.g == null ? '—' : round(r.g, 1) + '%'}</b></span><span class="tiny num ${r.tr ? (r.tr.perWeek >= 0.25 ? 'good' : r.tr.perWeek <= -0.25 ? 'bad' : 'muted') : 'dim'}">${r.tr ? `${r.tr.perWeek >= 0 ? '▲' : '▼'} ${Math.abs(round(r.tr.perWeek, 1))}/wk` : 'no trend'}</span><span class="tiny muted num" title="Estimate">${r.p != null ? '→ ' + round(r.p, 1) + '%' : ''}</span></a>`).join('')}</div>
        <p class="tiny dim" style="margin:10px 0 0">Arrows: measured trend. "→" values are projected end-of-term grades (estimates) scoring remaining work at your last 3 scores in each category.</p></div>
      <div class="card s-5"><div class="card-h"><h2>GPA</h2><span class="end">${tagMeas}</span></div>${lineChart([{ name: 'Unweighted GPA', color: 'var(--accent)', points: gs.map((y, i) => ({ i, y })) }], { labels: gd.map((d) => fmtDate(d)), min: Math.max(0, Math.floor(Math.min(4, ...gs.filter((x) => x != null)) - 0.5)), max: 4.2, fmt: (v) => v.toFixed(2), h: 190, empty: 'Appears once grades exist.', goal: pg ? round(pg.unweighted, 2) : null }).replace('>goal ', '>projected ')}<p class="tiny dim" style="margin:6px 0 0">Dashed line: projected GPA (estimate).</p></div>
      <div class="card s-6"><div class="card-h"><h2>Strengths & weaknesses by class</h2><span class="end tiny muted">now vs goal</span></div>${dumbbell(ranks.filter((r) => r.g != null).sort((a, b) => (b.g - (b.c.goal || b.g)) - (a.g - (a.c.goal || a.g))).map((r) => ({ label: r.c.name, a: r.g, b: r.c.goal || null, color: r.c.color })), { aLabel: 'current grade', bLabel: 'goal' })}</div>
      <div class="card s-6"><div class="card-h"><h2>By type of work & topic</h2></div>
        ${ta.length ? `<div class="small muted" style="margin-bottom:8px">Average score by type ${tagMeas}</div>${barChart(ta.map((x) => ({ label: TYPES[x.k] || x.k, value: x.v, sub: `${x.n} graded`, color: gradeColor(x.v) })), { horizontal: true, max: 100, fmt: (v) => round(v, 1) + '%' })}` : ''}
        ${ms.length ? `<div class="between small" style="margin:16px 0 8px"><span class="muted">Strongest topics</span><span class="muted">Weakest topics</span></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:8px">${[ms.slice(0, 3), [...ms].reverse().slice(0, 3)].map((list) => `<div class="stack" style="gap:6px">${list.map((m) => `<div class="mini-topic" style="--c:${MASTERY[m.status][1]}"><b>${esc(m.t.name)}</b><span class="tiny muted">${m.score}% · ${esc(clsName(m.t.classId))}</span></div>`).join('')}</div>`).join('')}</div>` : '<p class="small muted">Topic strengths appear once you study or quiz topics.</p>'}</div>
      <div class="card s-7"><div class="card-h"><h2>Most important today</h2><span class="end">${goBtn(['intel', 'director'], 'Study Director')}</span></div>${acts.length ? `<ol class="actions">${acts.map((a) => `<li class="lvl-${a.lvl}"><div><b>${esc(a.text)}</b><div class="small muted">${esc(a.why)}</div></div><button class="btn ghost sm" data-go='${esc(JSON.stringify(a.go))}'>${icon('arrow-right', 14)}</button></li>`).join('')}</ol>` : emptyState('circle-check', 'Nothing urgent', 'No high risks and no study recommendations for today.')}</div>
      <div class="card s-5"><div class="card-h"><h2>Upcoming risks</h2><span class="end">${goBtn(['intel', 'risks'], `All ${rk.length}`)}</span></div>${rk.length ? `<div class="stack" style="gap:8px">${rk.slice(0, 4).map((r) => `<div class="risk-mini" style="--c:${LVL[r.level][2]}"><div class="between"><b class="small">${esc(r.title)}</b>${lvlPill(r.level)}</div><div class="tiny muted">${esc(r.trigger)}</div></div>`).join('')}</div>` : emptyState('circle-check', 'No risks detected', 'The monitor checks grades, deadlines, exams, quizzes, study time and workload every time you open this page.')}</div>
      <div class="card s-12"><details><summary class="between" style="cursor:pointer"><h2>How the performance score is calculated</h2><span class="tiny muted">${icon('chevron-down', 14)}</span></summary>
        <p class="small muted">Each area is scored 0–100 from your records, then combined by weight. Areas with no data are left out and the remaining weights are scaled up, so a missing area never counts as zero.</p>
        <div class="table-wrap"><table class="table"><thead><tr><th>Area</th><th>Weight</th><th>Score</th><th>How it’s measured</th></tr></thead><tbody>${ps.comps.map((c) => `<tr><td><b>${c.k}</b></td><td class="num">${c.w}%</td><td class="num"><b style="color:${scoreColor(c.v)}">${Math.round(c.v * 100)}</b></td><td class="small">${esc(c.how)}</td></tr>`).join('')}${['Grades', 'Completion', 'On time', 'Consistency', 'Mastery', 'Practice'].filter((k) => !ps.comps.some((c) => c.k === k)).map((k) => `<tr><td class="muted">${k}</td><td class="num muted">—</td><td class="muted">—</td><td class="small muted">No data yet, so not counted.</td></tr>`).join('')}</tbody></table></div></details></div>
    </div>` };
}

// ---------- risks ----------
function riskDate(r) { if (r.aid) return byId('assignments', r.aid)?.due; if (r.id.startsWith('exam:')) return byId('exams', r.id.slice(5))?.date; if (r.id.startsWith('week:')) return r.id.slice(5); if (r.id.startsWith('cluster:')) return r.id.slice(8, 18); return null; }
function intelRisks() {
  const all = risks(), list = all.filter((r) => (IV.risk === 'all' || r.level === IV.risk) && (!IV.riskCls || r.classId === IV.riskCls));
  const n = (l) => all.filter((r) => r.level === l).length, t = today();
  const days = Array.from({ length: 15 }, (_, i) => addDays(t, i - 1)), dated = all.map((r) => ({ r, d: riskDate(r) })).filter((x) => x.d);
  return { sub: `${all.length} risk${all.length === 1 ? '' : 's'} detected from your current data`,
    html: `<div class="grid g-12"><div class="card s-4"><div class="card-h"><h2>Risk level</h2></div><div class="risk-counts">${['high', 'medium', 'low'].map((l) => `<button class="rc${IV.risk === l ? ' on' : ''}" data-rl="${l}" style="--c:${LVL[l][2]}"><b class="num">${n(l)}</b><span>${LVL[l][1]}</span></button>`).join('')}</div>
        <div class="stackbar" style="margin-top:14px">${['high', 'medium', 'low'].map((l) => n(l) ? `<i style="flex:${n(l)};background:${LVL[l][2]}"></i>` : '').join('') || '<i style="flex:1;background:var(--good)"></i>'}</div>
        <p class="tiny dim" style="margin:10px 0 0">The monitor re-checks every time your data changes: grades, deadlines, missing work, exam readiness, quiz accuracy by topic, study time per class and weekly workload.</p></div>
      <div class="card s-8"><div class="card-h"><h2>Risk timeline</h2><span class="end tiny muted">next 2 weeks</span></div><div class="rtl">${days.map((d) => { const hs = dated.filter((x) => x.d === d || (x.d < t && d === addDays(t, -1))); return `<div class="rtl-d${d === t ? ' today' : ''}"><span class="tiny ${d === t ? '' : 'muted'}">${d < t ? 'Past' : DAYS[dow(d)]}</span><b class="tiny">${d < t ? '' : +d.slice(8)}</b><div class="rtl-m">${hs.map((x) => `<i style="background:${LVL[x.r.level][2]}" data-tip="${esc(`<b>${esc(x.r.title)}</b><br>${LVL[x.r.level][1]} · ${esc(x.r.type)}`)}"></i>`).join('')}</div></div>`; }).join('')}</div>
        <p class="tiny dim" style="margin:8px 0 0">Dots mark risks tied to a date (deadlines, exams, busy weeks). Overdue items sit in "Past".</p></div></div>
    <div class="row wrap" style="gap:8px"><div class="chips" id="rk-l">${[['all', 'All levels'], ['high', 'High'], ['medium', 'Medium'], ['low', 'Low']].map(([k, l]) => `<button class="chip${IV.risk === k ? ' on' : ''}" data-rl="${k}">${l}</button>`).join('')}</div><select id="rk-c" style="width:auto">${classOptions(IV.riskCls, 'All classes')}</select></div>
    ${list.length ? `<div class="risk-grid">${list.map((r) => `<article class="risk" style="--c:${LVL[r.level][2]}"><header class="between"><span class="row" style="gap:6px">${lvlPill(r.level)}<span class="badge">${esc(r.type)}</span></span>${clsChip(r.classId)}</header><h3>${esc(r.title)}</h3>
      <dl><dt>${icon('zap', 13)} Triggered by</dt><dd>${esc(r.trigger)}</dd><dt>${icon('info', 13)} Why it matters</dt><dd>${esc(r.why)}</dd><dt>${icon('arrow-right', 13)} Next action</dt><dd><b>${esc(r.action)}</b></dd></dl>
      <footer>${goBtn(r.go, 'Go to it')}${r.aid ? `<button class="btn ghost sm" onclick="openAssignment('${r.aid}')">Details</button>` : ''}</footer></article>`).join('')}</div>` : `<div class="card">${emptyState('circle-check', all.length ? 'No risks match these filters' : 'No risks detected', all.length ? 'Try another level or class.' : 'Nothing in your current grades, deadlines, exams, quizzes, study time or workload crosses a warning threshold.')}</div>`}`,
    mount(root) { root.addEventListener('click', (e) => { const b = e.target.closest('[data-rl]'); if (b) { IV.risk = IV.risk === b.dataset.rl && b.classList.contains('rc') ? 'all' : b.dataset.rl; render(); } }); $('#rk-c', root).onchange = (e) => { IV.riskCls = e.target.value; render(); }; } };
}

// ---------- grade simulator ----------
const SIM = { cid: null, items: [], pcts: {}, target: null, saved: [], extra: [] };
function simLoad(cid) { const c = cls(cid); SIM.cid = cid; SIM.items = [...remainingItems(cid), ...SIM.extra.filter((x) => x.cid === cid)]; const st = catStats(cid); SIM.pcts = Object.fromEntries(SIM.items.map((x) => [x.id, st.n ? Math.round(st.avg(x.cat)) : 85])); SIM.target = c.goal || 90; SIM.saved = []; }
function intelSim() {
  const c = cls(IV.cid); if (SIM.cid !== c.id) simLoad(c.id);
  const sc = scenarios(c.id, SIM.items), req = requiredUniform(c.id, SIM.target, SIM.items), mine = SIM.items.some((x) => x.counted) ? gradeWith(c.id, SIM.items, (x) => SIM.pcts[x.id] ?? 0) : sc.cur;
  const curve = Array.from({ length: 11 }, (_, i) => (SIM.items.some((x) => x.counted) ? round(gradeWith(c.id, SIM.items, () => i * 10), 2) : null));
  const allRows = S.classes.map((k) => { const tg = k.goal || 90, rq = requiredUniform(k.id, tg), s = scenarios(k.id); return { k, tg, rq, s, re: rq.status === 'needed' ? realism(k.id, rq.p) : null }; });
  const scen = [['Worst case', sc.zero, 'every remaining item scored 0', 'var(--bad)'], ['Low', sc.low, 'your lowest past score in each category', 'var(--warn)'], ['Expected', sc.expected, sc.n >= 3 ? 'your last 3 scores in each category' : 'needs 3+ graded items', 'var(--accent)'], ['Your scenario', mine, 'the sliders below', 'var(--accent-2)'], ['Best case', sc.best, '100% on everything left', 'var(--good)'], ...SIM.saved.map((s) => [s.name, s.v, 'saved scenario', '#94a3b8'])];
  return { sub: 'What-if scenarios use the same formula as your gradebook. Nothing here changes your real grades.',
    html: classChips('sim-c', c.id) + `<div class="sim-top">${[['Current', sc.cur, 'Actual', 'o'], ['Target', SIM.target, 'Your goal', 's'], ['Needed on remaining', req.status === 'needed' ? req.p : null, req.status === 'secured' ? 'Already secured' : req.status === 'impossible' ? 'Not reachable' : req.status === 'none' ? 'No remaining work entered' : 'Average on each item', 'a'], ['Best case', sc.best, 'Estimate', 'a'], ['Expected', sc.expected, sc.expected == null ? 'Needs 3+ grades' : 'Estimate', 'a'], ['Worst case', sc.zero, 'Estimate', 'a']].map(([l, v, s, k], i) => `<div class="sim-k${i === 1 ? ' tgt' : ''}"><span class="tiny muted">${l}</span>${i === 1 ? `<div class="row" style="gap:4px"><input type="number" id="sim-t" value="${SIM.target}" min="0" max="110" step="0.5" style="width:84px;font:700 20px var(--f-display);padding:4px 8px"><b>%</b></div>` : `<b class="num" style="color:${i === 2 ? (req.status === 'impossible' ? 'var(--bad)' : 'var(--fg)') : gradeColor(v)}">${v == null ? (req.status === 'secured' && i === 2 ? '✓' : req.status === 'impossible' && i === 2 ? '✕' : '—') : round(v, 2) + '%'}</b>`}<span class="tag-obs ${k}">${s}</span></div>`).join('')}</div>
      ${req.status === 'needed' ? (() => { const re = realism(c.id, req.p); return re ? `<div class="alert ${re.k === 'good' ? 'good' : re.k === 'warn' ? 'warn' : re.k === 'bad' ? 'bad' : 'info'}"><span class="ai">${icon('target', 15)}</span><span><b>To finish at ${SIM.target}%: average ${round(req.p, 1)}% on the ${SIM.items.filter((x) => x.counted).length} remaining graded item${SIM.items.filter((x) => x.counted).length === 1 ? '' : 's'}.</b> ${esc(re.label)}.</span></div>` : ''; })() : req.status === 'impossible' ? `<div class="alert bad"><span class="ai">${icon('circle-x', 15)}</span><span><b>${SIM.target}% isn’t reachable with the work entered.</b> Perfect scores on everything left give ${round(req.best, 2)}%. Add upcoming assignments if some are missing, or ask about extra credit.</span></div>` : ''}
      <div class="grid g-12"><div class="card s-6"><div class="card-h"><h3>Remaining work</h3><span class="end row"><button class="btn ghost sm" data-fill="exp" ${sc.n >= 3 ? '' : 'disabled'}>Expected</button><button class="btn ghost sm" data-fill="req" ${req.status === 'needed' ? '' : 'disabled'}>Needed</button><button class="btn ghost sm" data-fill="100">All 100</button></span></div>
        ${SIM.items.length ? `<div class="stack" style="gap:10px" id="sim-items">${SIM.items.map((x) => `<div class="sim-item${x.counted ? '' : ' off'}" data-i="${x.id}"><div class="between"><span style="min-width:0"><b class="small">${esc(x.title)}</b><div class="tiny muted">${esc(x.kind)} · ${x.due ? fmtDate(x.due) : 'no date'} · ${esc(c.categories?.find((k) => k.id === x.cat)?.name || (c.gradingMode === 'points' ? 'points' : 'no category'))}${x.late ? ' · <span class="bad">overdue</span>' : ''}${x.hypo ? ' · hypothetical' : ''}</div></span><span class="row" style="gap:4px"><input type="number" data-max value="${x.max}" min="1" step="any" style="width:68px;padding:4px 6px" aria-label="Points possible" title="${x.assumedMax ? 'Points not entered; assumed 100' : 'Points possible'}"><span class="tiny ${x.assumedMax ? 'warn' : 'muted'}">pts${x.assumedMax ? '*' : ''}</span></span></div>
          ${x.counted ? `<div class="row" style="gap:10px;margin-top:6px"><input type="range" min="0" max="100" step="1" value="${SIM.pcts[x.id]}" data-p aria-label="Score for ${esc(x.title)}"><b class="num small" style="width:44px;text-align:right" data-pv>${SIM.pcts[x.id]}%</b></div>` : `<div class="tiny warn" style="margin-top:4px">Not counted: give it a grade category to include it.</div>`}</div>`).join('')}</div>${SIM.items.some((x) => x.assumedMax) ? '<p class="tiny dim" style="margin:8px 0 0">* No points entered for this item, so 100 is assumed. Change it to match the real assignment.</p>' : ''}` : emptyState('list-checks', 'No ungraded work', 'Add upcoming assignments or exams to this class, or add a hypothetical item below.')}
        <form class="row wrap" id="sim-add" style="gap:6px;margin-top:12px"><input type="text" placeholder="Hypothetical item (e.g. Final exam)" id="sa-t" style="flex:2;min-width:150px"><select id="sa-c" style="width:auto;flex:1">${c.gradingMode === 'points' || !(c.categories || []).length ? '<option value="">Points</option>' : c.categories.map((k) => `<option value="${k.id}">${esc(k.name)}</option>`).join('')}</select><input type="number" id="sa-m" value="100" min="1" style="width:76px" aria-label="Points"><button class="btn sm" type="submit">${icon('plus', 14)} Add</button></form></div>
      <div class="s-6 stack" style="gap:18px;align-content:start"><div class="card"><div class="card-h"><h3>Final grade vs. score on remaining work</h3></div>${lineChart([{ name: 'Final grade', color: c.color, points: curve.map((y, i) => ({ i, y, label: `${i * 10}% on everything left` })) }], { labels: curve.map((_, i) => i * 10 + '%'), goal: SIM.target, fmt: (v) => v + '%', h: 200, empty: 'Add remaining work to see the curve.' }).replace('>goal ', '>target ')}<p class="tiny dim" style="margin:6px 0 0">Where the line crosses the target is the average you need.</p></div>
        <div class="card"><div class="card-h"><h3>Compare outcomes</h3><span class="end"><button class="btn sm" id="sim-save">${icon('copy', 14)} Save my scenario</button></span></div>${barChart(scen.filter((s) => s[1] != null).map(([l, v, sub, col]) => ({ label: l, value: v, sub, color: col })), { horizontal: true, max: 100, fmt: (v) => round(v, 2) + '%' })}<p class="tiny dim" style="margin:8px 0 0">All of these are estimates except "Current". Target: ${SIM.target}%.</p></div></div></div>
      <div class="card"><div class="card-h"><h3>Every class at its goal</h3><span class="end tiny muted">targets are each class’s goal</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Class</th><th>Current</th><th>Goal</th><th>Needed avg.</th><th>Realistic?</th><th>Best</th><th>Expected</th></tr></thead><tbody>${allRows.map(({ k, tg, rq, s, re }) => `<tr style="cursor:pointer" onclick="IV.cid='${k.id}';go('intel','sim','${k.id}')"><td><span class="row"><i class="dot-c" style="--c:${k.color}"></i><b>${esc(k.name)}</b></span></td><td class="num">${s.cur == null ? '—' : round(s.cur, 2) + '%'}</td><td class="num">${tg}%</td><td class="num"><b>${rq.status === 'needed' ? round(rq.p, 1) + '%' : rq.status === 'secured' ? 'secured' : rq.status === 'impossible' ? 'not reachable' : '—'}</b></td><td class="small ${re ? re.k : ''}">${re ? esc(re.label) : rq.status === 'secured' ? 'Already locked in' : rq.status === 'none' ? 'No remaining work entered' : rq.status === 'impossible' ? 'Even 100% falls short' : ''}</td><td class="num">${s.best == null ? '—' : round(s.best, 1) + '%'}</td><td class="num">${s.expected == null ? '—' : round(s.expected, 1) + '%'}</td></tr>`).join('')}</tbody></table></div></div>`,
    mount(root) {
      $('#sim-c', root).onclick = (e) => { const b = e.target.closest('[data-c]'); if (b) go('intel', 'sim', b.dataset.c); };
      const recalc = () => { const y = scrollY; render(); scrollTo(0, y); };
      $('#sim-t', root).onchange = (e) => { const v = Number(e.target.value); if (v > 0) { SIM.target = v; recalc(); } };
      $('#sim-items', root)?.addEventListener('input', (e) => { const row = e.target.closest('[data-i]'); if (!row) return; if (e.target.matches('[data-p]')) { SIM.pcts[row.dataset.i] = +e.target.value; $('[data-pv]', row).textContent = e.target.value + '%'; } });
      $('#sim-items', root)?.addEventListener('change', (e) => { const row = e.target.closest('[data-i]'); if (!row) return; if (e.target.matches('[data-max]')) { const v = Number(e.target.value); const it = SIM.items.find((x) => x.id === row.dataset.i); if (v > 0) { it.max = v; it.assumedMax = false; } } recalc(); });
      root.addEventListener('click', (e) => { const f = e.target.closest('[data-fill]'); if (!f) return; const st = catStats(c.id), rq = requiredUniform(c.id, SIM.target, SIM.items); for (const x of SIM.items) SIM.pcts[x.id] = f.dataset.fill === '100' ? 100 : f.dataset.fill === 'exp' ? Math.round(st.recent(x.cat)) : Math.ceil(rq.p); recalc(); });
      $('#sim-save', root).onclick = () => { const v = SIM.items.some((x) => x.counted) ? gradeWith(c.id, SIM.items, (x) => SIM.pcts[x.id] ?? 0) : null; if (v == null) return toast('Nothing to save yet'); SIM.saved.push({ name: `Scenario ${String.fromCharCode(65 + SIM.saved.length)}`, v }); if (SIM.saved.length > 4) SIM.saved.shift(); recalc(); };
      $('#sim-add', root).onsubmit = (e) => { e.preventDefault(); const t = $('#sa-t', root).value.trim() || 'Hypothetical item', m = Number($('#sa-m', root).value) || 100, cat = $('#sa-c', root).value; const it = { id: uid('h'), cid: c.id, title: t, kind: 'Hypothetical', due: '', cat, max: m, counted: c.gradingMode === 'points' || !(c.categories || []).length || !!cat, hypo: true }; SIM.extra.push(it); SIM.items.push(it); SIM.pcts[it.id] = Math.round(catStats(c.id).avg(cat) || 85); recalc(); };
    } };
}

// ---------- study director ----------
function intelDirector() {
  const t = today(), recs = directorRecs(), budget = S.settings.dailyStudyMins || 60, studied = studyMinsOn(t);
  const live = recs.filter((r) => r.status !== 'dismissed' && r.status !== 'scheduled');
  // Exam-plan sessions due today are commitments you already made, so they always go in. Other study fills the study budget;
  // assignment work fills your daily homework capacity.
  let left = Math.max(0, budget - studied), wleft = workCap(); const plan = [], more = [];
  for (const r of live) {
    if (r.status === 'done' || r.status === 'accepted') { plan.push(r); if (r.kind === 'assignment') wleft -= r.mins; else left -= r.mins; continue; }
    const open = plan.filter((p) => p.status === 'open').length;
    if (r.kind === 'exam-plan') { plan.push(r); left -= r.mins; }
    else if (r.kind === 'assignment' ? wleft >= 20 : left >= 10) { if (open >= 7) { more.push(r); continue; } plan.push(r); if (r.kind === 'assignment') wleft -= r.mins; else left -= r.mins; }
    else more.push(r);
  }
  const sched = recs.filter((r) => r.status === 'scheduled'), dism = recs.filter((r) => r.status === 'dismissed');
  const planned = sum(plan.filter((r) => r.status !== 'done' && r.kind !== 'assignment').map((r) => r.mins));
  const free = (() => { const s0 = toMin(S.settings.studyStart), e0 = toMin(S.settings.studyEnd), n = new Date(), from = Math.max(s0, n.getHours() * 60 + n.getMinutes()); if (from >= e0) return 0; const busy = itemsOn(t).filter((i) => i.s != null && i.e != null && !i.logged && i.k !== 'due').map((i) => [Math.max(from, i.s), Math.min(e0, i.e)]).filter(([a, b]) => b > a); let tot = e0 - from; busy.sort((a, b) => a[0] - b[0]); let cur = from; for (const [a, b] of busy) { if (b <= cur) continue; tot -= b - Math.max(a, cur); cur = b; } return Math.max(0, tot); })();
  const card = (r, i) => { const ev = r.dec?.eventId ? byId('events', r.dec.eventId) : null; return `<article class="rec${r.status === 'done' ? ' done' : ''}" data-key="${esc(r.key)}" style="--c:${clsColor(r.classId)}">
    <div class="rec-n">${r.status === 'done' ? icon('check', 16) : i + 1}</div><div class="grow" style="min-width:0">
    <div class="between" style="gap:8px"><span class="row wrap" style="gap:6px"><span class="badge ${r.priority === 'High' ? 'bad' : r.priority === 'Medium' ? 'warn' : ''}">${r.priority}</span>${clsChip(r.classId)}${ev ? `<span class="badge accent">${icon('calendar', 11)} ${ev.date === t ? '' : fmtDate(ev.date) + ' '}${fmtTime(ev.start)}</span>` : ''}${r.status === 'done' ? '<span class="badge good">Done today</span>' : ''}</span><b class="num">${fmtMins(r.mins)}</b></div>
    <h3 style="margin:6px 0 2px">${esc(r.topic)}</h3><p class="small muted" style="margin:0"><b style="color:var(--fg-2)">Why:</b> ${esc(r.reason)}</p><p class="small" style="margin:4px 0 0"><b>How:</b> ${esc(METHODS[r.method])}</p>
    ${r.status === 'done' ? '' : `<div class="row wrap" style="gap:6px;margin-top:10px"><button class="btn primary sm" data-act="start">${icon('play', 13)} Start now</button>${r.status === 'accepted' ? '' : `<button class="btn sm" data-act="accept">${icon('calendar-plus', 13)} Add to today</button>`}<button class="btn ghost sm" data-act="edit">${icon('pencil', 13)} Edit</button><button class="btn ghost sm" data-act="resched">${icon('calendar-clock', 13)} Reschedule</button><button class="btn ghost sm" data-act="dismiss">${icon('x', 13)} Dismiss</button></div>`}</div></article>`; };
  return { sub: 'Recommendations rebuild whenever grades, assignments, quizzes, flashcards or study sessions change',
    html: `<div class="dir-top card"><div class="grow"><div class="between small"><b>Today’s study budget</b><span class="muted">${fmtMins(studied)} studied · ${fmtMins(planned)} study recommended · ${fmtMins(budget)} goal${studied + planned > budget ? ' <span class="warn">(over goal: includes exam-plan sessions you already scheduled)</span>' : ''}</span></div>
        <div class="stackbar big" style="margin-top:8px">${studied ? `<i style="flex:${Math.min(studied, budget * 1.5)};background:var(--good)" data-tip="Studied today: ${fmtMins(studied)}"></i>` : ''}${planned ? `<i style="flex:${planned};background:var(--accent)" data-tip="Recommended: ${fmtMins(planned)}"></i>` : ''}${Math.max(0, budget - studied - planned) ? `<i style="flex:${budget - studied - planned};background:var(--raised-2)"></i>` : ''}</div>
        <div class="legend"><span><i class="dot-c" style="--c:var(--good)"></i>Studied (measured)</span><span><i class="dot-c"></i>Recommended</span><span class="muted">Homework in plan: ${fmtMins(sum(plan.filter((r) => r.kind === 'assignment' && r.status !== 'done').map((r) => r.mins)))} of ${fmtMins(workCap())} capacity · free time left in your study hours today: ${fmtMins(free)} (from the planner)</span></div></div>
        <a class="btn ghost sm" href="#settings">${icon('settings', 14)} Budget</a></div>
      <div class="grid g-12"><div class="s-7 stack" style="gap:12px;align-content:start"><h2 style="margin:4px 0 0">Today’s plan</h2>${plan.length ? plan.map(card).join('') : `<div class="card">${emptyState('circle-check', 'Nothing to recommend', 'No exams soon, no weak topics, no due flashcards and no urgent assignments. Add exams and topics, or quiz yourself, and the Director will plan from them.')}</div>`}</div>
        <div class="s-5 stack" style="gap:12px;align-content:start"><h2 style="margin:4px 0 0">If you have more time</h2>${more.length ? more.slice(0, 6).map((r, i) => card(r, plan.length + i)).join('') : '<p class="small muted">Nothing else right now.</p>'}
          ${sched.length ? `<div class="card"><div class="card-h"><h3>Rescheduled</h3></div><div class="list">${sched.map((r) => { const ev = r.dec?.eventId && byId('events', r.dec.eventId); return `<div class="li"><span class="cbar" style="--c:${clsColor(r.classId)}"></span><span class="grow"><span class="t">${esc(r.topic)}</span><div class="s">${ev ? fmtDay(ev.date) + ' · ' + fmtTime(ev.start) : ''}</div></span></div>`; }).join('')}</div></div>` : ''}
          ${dism.length ? `<div class="card"><div class="card-h"><h3>Dismissed today</h3></div><div class="list">${dism.map((r) => `<div class="li" data-key="${esc(r.key)}"><span class="grow small">${esc(r.topic)}</span><button class="btn ghost sm" data-act="restore">Restore</button></div>`).join('')}</div></div>` : ''}
          <div class="card"><div class="card-h"><h3>How recommendations are chosen</h3></div><p class="small muted" style="margin:0">Fixed rules rank candidates from your data: exam plan sessions due today, exam topics weighted by how close the exam is and how low your mastery is, topics with weak quiz accuracy, decks with 5+ due cards, topics not studied in 10+ days, assignments due within 3 days, and classes under goal that got little study time. The plan fills your daily study budget from the top.</p></div></div></div>`,
    mount(root) {
      root.addEventListener('click', (e) => {
        const b = e.target.closest('[data-act]'), el = b?.closest('[data-key]'); if (!b || !el) return;
        const r = recs.find((x) => x.key === el.dataset.key); if (!r) return; const act = b.dataset.act;
        const setDec = (patch) => { const id = r.key + '|' + t; const old = S.recs.find((x) => x.id === id) || { id, key: r.key, date: t }; upsert('recs', { ...old, ...patch }); };
        if (act === 'start') { startTimerFor(r.classId, r.topic, r.aid || null); return; }
        if (act === 'dismiss') { setDec({ status: 'dismissed' }); toast('Dismissed for today', { label: 'Undo', fn: () => setDec({ status: 'open' }) }); return; }
        if (act === 'restore') { setDec({ status: 'open' }); return; }
        if (act === 'accept') { const st = freeSlot(t, r.mins); if (st == null) return toast('No free slot left in your study hours today. Try Reschedule.'); const ev = { id: uid('v'), title: `Study: ${r.topic}`, date: t, start: fromMin(st), end: fromMin(st + r.mins), allDay: false, kind: 'study', classId: r.classId, color: '', weekly: false, until: '', notes: `${METHODS[r.method]}\nWhy: ${r.reason}`, recKey: r.key }; upsert('events', ev); setDec({ status: 'accepted', eventId: ev.id }); toast(`Added to your planner at ${fmtTime(ev.start)}`); return; }
        if (act === 'edit' || act === 'resched') {
          const ev0 = r.dec?.eventId ? byId('events', r.dec.eventId) : null;
          modal({ title: act === 'edit' ? 'Edit recommendation' : 'Reschedule', icon: act === 'edit' ? 'pencil' : 'calendar-clock', body: `<p class="small muted" style="margin:0">${esc(r.topic)} · ${esc(clsName(r.classId))}</p><div class="fgrid"><label class="f">Minutes<input type="number" id="re-m" value="${r.mins}" min="5" max="240" step="5"></label>${act === 'edit' ? `<label class="f">Method<select id="re-me">${Object.entries(METHODS).map(([k, v]) => `<option value="${k}"${r.method === k ? ' selected' : ''}>${esc(v.split(':')[0])}</option>`).join('')}</select></label>` : `<label class="f">Date<input type="date" id="re-d" value="${ev0?.date || addDays(t, 1)}" min="${t}"></label><label class="f">Start<input type="time" id="re-s" value="${ev0?.start || fromMin(freeSlot(addDays(t, 1), r.mins) ?? toMin(S.settings.studyStart))}"></label>`}</div>`,
            foot: `<button class="btn primary" data-ok>Save</button>`, onMount: (m, close) => { $('[data-ok]', m).onclick = () => { const mins = Number($('#re-m', m).value); if (!(mins > 0)) return toast('Enter minutes'); if (act === 'edit') { setDec({ mins, method: $('#re-me', m).value, status: r.dec?.status || 'open' }); if (ev0) { ev0.end = fromMin(toMin(ev0.start) + mins); save('events'); } close(); return; }
              const d = $('#re-d', m).value, s = $('#re-s', m).value; if (!d || !s) return toast('Pick a date and time'); const ev = { ...(ev0 || { id: uid('v'), kind: 'study', classId: r.classId, color: '', weekly: false, until: '', allDay: false, recKey: r.key }), title: `Study: ${r.topic}`, date: d, start: s, end: fromMin(Math.min(toMin(s) + mins, 1439)), notes: `${METHODS[r.method]}\nWhy: ${r.reason}` }; upsert('events', ev);
              if (d === t) setDec({ status: 'accepted', eventId: ev.id, mins }); else { setDec({ status: 'scheduled', eventId: ev.id, mins }); upsert('recs', { id: r.key + '|' + d, key: r.key, date: d, status: 'accepted', eventId: ev.id, mins }); }
              close(); toast(`Scheduled ${fmtDay(d)} at ${fmtTime(s)}`); }; } });
        }
      });
    } };
}

// ---------- topic mastery ----------
function masteryMap(cid, compact = false) {
  const ts = topicsOf(cid).map(topicMastery), units = [...new Set(ts.map((m) => m.t.unit || ''))].sort((a, b) => (a || 'zzz').localeCompare(b || 'zzz'));
  const cnt = (s) => ts.filter((m) => m.status === s).length;
  const tile = (m) => { const [l, col] = MASTERY[m.status]; return `<button class="mtile" data-tid="${m.t.id}" style="--c:${col}"><div class="between" style="align-items:flex-start"><b>${esc(m.t.name)}</b>${ring(m.score ?? 0, m.score == null ? '–' : m.score, '', 40, col, 4)}</div><span class="mt-st">${l}</span><div class="mt-meta"><span title="Quiz accuracy">${icon('circle-help', 11)} ${m.recentAcc == null ? '—' : Math.round(m.recentAcc * 100) + '%'}</span><span title="Flashcard retention">${icon('layers', 11)} ${m.cardStr == null ? '—' : Math.round(m.cardStr * 100) + '%'}</span><span title="Study sessions">${icon('timer', 11)} ${m.sessions}</span><span title="Last studied">${icon('clock', 11)} ${m.daysSince == null ? 'never' : m.daysSince === 0 ? 'today' : m.daysSince + 'd'}</span></div></button>`; };
  return `<div class="mastery-sum"><div class="stackbar big" style="flex:1">${Object.keys(MASTERY).map((s) => cnt(s) ? `<i style="flex:${cnt(s)};background:${MASTERY[s][1]}" data-tip="${MASTERY[s][0]}: ${cnt(s)}"></i>` : '').join('') || '<i style="flex:1;background:var(--raised-2)"></i>'}</div><div class="legend" style="margin:0">${Object.entries(MASTERY).map(([s, [l, c]]) => `<span><i class="dot-c" style="--c:${c}"></i>${l} <b>${cnt(s)}</b></span>`).join('')}</div></div>
    ${ts.length ? units.map((u) => `<div class="m-unit">${units.length > 1 || u ? `<h4>${esc(u || 'No unit')}</h4>` : ''}<div class="mgrid${compact ? ' compact' : ''}">${ts.filter((m) => (m.t.unit || '') === u).map(tile).join('')}</div></div>`).join('') : emptyState('layout-grid', 'No topics yet', 'Add the topics this class covers. Exam topics are added automatically. Link flashcard decks to topics so quizzes and reviews count toward mastery.')}`;
}
function intelMastery() {
  const c = cls(IV.cid), ts = topicsOf(c.id).map(topicMastery), sc = ts.filter((m) => m.score != null);
  return { sub: 'Mastery comes from quiz answers, flashcard reviews and study sessions, not from opening a topic',
    html: classChips('ms-c', c.id) + `<div class="grid g-12"><div class="card s-8"><div class="card-h"><h2>${esc(c.name)} mastery map</h2><span class="end tiny muted">${sc.length ? `average ${Math.round(avg(sc.map((m) => m.score)))}% across ${sc.length} active topic${sc.length === 1 ? '' : 's'}` : ''}</span></div>${masteryMap(c.id)}
      <form class="row wrap" id="tp-add" style="gap:6px;margin-top:14px"><input type="text" id="tp-n" placeholder="Add a topic (e.g. Cellular respiration)" style="flex:2;min-width:180px" aria-label="Topic name"><input type="text" id="tp-u" placeholder="Unit (optional)" style="flex:1;min-width:120px" list="tp-units" aria-label="Unit"><datalist id="tp-units">${[...new Set(topicsOf(c.id).map((t) => t.unit).filter(Boolean))].map((u) => `<option value="${esc(u)}">`).join('')}</datalist><button class="btn primary sm" type="submit">${icon('plus', 14)} Add topic</button></form></div>
      <div class="s-4 stack" style="gap:18px;align-content:start"><div class="card"><div class="card-h"><h3>How mastery is measured</h3></div><div class="stack small" style="gap:8px">${[['Quiz accuracy', '40%', 'answers on this topic’s cards in quizzes and practice tests (last 3 quizzes)'], ['Flashcard retention', '35%', 'review interval ÷ 21 days for each reviewed card; overdue cards count less'], ['Your confidence', '15%', 'the exam topic rating, only once there is real activity'], ['Practice & recency', '10%', 'sessions and reviews, fading after 7 and 21 days']].map(([k, w, d]) => `<div><b>${k}</b> <span class="muted">${w}</span><div class="tiny muted">${d}</div></div>`).join('')}<p class="tiny dim" style="margin:4px 0 0"><b>Mastered</b> needs a score of 85+, quiz or flashcard evidence, activity in the last 21 days and 80%+ recent quiz accuracy. <b>Needs review</b>: under 60, quiz accuracy under 70%, or 14+ days since you studied it.</p></div></div>
        <div class="card"><div class="card-h"><h3>Link study material</h3></div><p class="small muted" style="margin:0 0 8px">Decks linked to a topic feed its quiz and flashcard scores. Timer sessions count when the topic name is in the session’s topic.</p>${S.decks.filter((d) => d.classId === c.id).map((d) => `<label class="f" style="margin-bottom:8px">${esc(d.name)}${S.cards.some((x) => x.deckId === d.id && x.topicId) ? ' <span class="tiny dim">(some cards tagged individually)</span>' : ''}<select data-deck="${d.id}"><option value="">Not linked</option>${topicsOf(c.id).map((t) => `<option value="${t.id}"${d.topicId === t.id ? ' selected' : ''}>${esc(t.name)}</option>`).join('')}</select></label>`).join('') || '<p class="tiny dim">No decks in this class.</p>'}</div></div></div>`,
    mount(root) {
      $('#ms-c', root).onclick = (e) => { const b = e.target.closest('[data-c]'); if (b) go('intel', 'mastery', b.dataset.c); };
      $('#tp-add', root).onsubmit = (e) => { e.preventDefault(); const n = $('#tp-n', root).value.trim(); if (!n) return; if (topicByName(c.id, n)) return toast('That topic already exists'); upsert('topics', { id: uid('tp'), classId: c.id, name: n, unit: $('#tp-u', root).value.trim(), createdAt: Date.now() }); toast('Topic added'); render(); setTimeout(() => $('#tp-n')?.focus(), 30); };
      root.addEventListener('change', (e) => { const d = e.target.dataset.deck; if (d) { const dk = byId('decks', d); dk.topicId = e.target.value || undefined; save('decks'); } });
      root.addEventListener('click', (e) => { const b = e.target.closest('[data-tid]'); if (b) topicDetail(b.dataset.tid); });
    } };
}
function topicDetail(id) {
  const t = byId('topics', id); if (!t) return; const m = topicMastery(t), cards = topicCards(t), sess = S.sessions.filter((s) => sessMatch(s, t)).sort((a, b) => b.start - a.start);
  const exams = S.exams.filter((e) => e.classId === t.classId && (e.topics || []).some((x) => low(x.name) === low(t.name)));
  modal({ title: t.name, icon: 'layout-grid', wide: true, headEnd: `<span class="badge" style="color:${MASTERY[m.status][1]}">${MASTERY[m.status][0]}</span>`,
    body: `<div class="row wrap" style="gap:20px;align-items:center">${ring(m.score ?? 0, m.score == null ? '—' : m.score + '%', 'mastery', 120, MASTERY[m.status][1])}<div class="grow stack" style="gap:8px;min-width:240px">${m.parts.map((p) => `<div><div class="between small"><span>${p.k} <span class="dim">(${p.w}%)</span></span><b class="num">${p.v == null ? '—' : Math.round(p.v * 100) + '%'}</b></div><div class="bar" style="height:5px;margin:3px 0"><i style="width:${(p.v ?? 0) * 100}%;--c:${scoreColor(p.v)}"></i></div><div class="tiny muted">${esc(p.src)}</div></div>`).join('')}</div></div>
      ${m.quizSeries.length >= 2 ? `<div><div class="small muted" style="margin-bottom:6px">Quiz accuracy on this topic</div>${lineChart([{ name: 'Accuracy', color: 'var(--accent)', points: m.quizSeries.map((q, i) => ({ i, y: Math.round(q.acc * 100) })) }], { labels: m.quizSeries.map((q) => fmtDate(isoOf(new Date(q.at)))), min: 0, max: 100, h: 150, fmt: (v) => v + '%' })}</div>` : ''}
      <div class="fgrid"><div><div class="small muted" style="margin-bottom:6px">Cards (${cards.length})</div>${cards.length ? `<div class="list">${cards.slice(0, 6).map((c) => `<div class="li" style="padding:6px 2px"><span class="grow small">${esc(c.front)}</span><span class="tiny" style="color:${cardLevel(c)[1]}">${cardLevel(c)[0]}</span></div>`).join('')}</div>` : '<p class="tiny dim" style="margin:0">No cards linked. Link a deck on the mastery page or set a topic on individual cards.</p>'}</div>
        <div><div class="small muted" style="margin-bottom:6px">Sessions (${sess.length} · ${fmtMins(m.mins)})</div>${sess.length ? `<div class="list">${sess.slice(0, 5).map(sessionRow).join('')}</div>` : '<p class="tiny dim" style="margin:0">None yet. Start the timer with this topic name.</p>'}${exams.length ? `<div class="small muted" style="margin:10px 0 4px">On exams</div>${exams.map((e) => `<a href="#exams/${e.id}" class="badge accent" style="text-decoration:none;margin:0 4px 4px 0">${esc(e.title)} · ${fmtDate(e.date)}</a>`).join('')}` : ''}</div></div>
      <div class="fgrid"><label class="f">Name<input type="text" id="td-n" value="${esc(t.name)}"></label><label class="f">Unit<input type="text" id="td-u" value="${esc(t.unit || '')}"></label></div>`,
    foot: `<button class="btn ghost danger" data-del>${icon('trash-2', 14)} Delete topic</button><span class="grow"></span>${cards.length >= 2 ? `<button class="btn" data-quiz>${icon('circle-help', 14)} Quiz this topic</button>` : ''}<button class="btn" data-study>${icon('timer', 14)} Study now</button><button class="btn primary" data-save>Save</button>`,
    onMount: (r, close) => {
      $('[data-save]', r).onclick = () => { const n = $('#td-n', r).value.trim(); if (!n) return; t.name = n; t.unit = $('#td-u', r).value.trim(); save('topics'); close(); };
      $('[data-study]', r).onclick = () => { close(); startTimerFor(t.classId, t.name); };
      $('[data-quiz]', r)?.addEventListener('click', () => { close(); runQuiz(makeQuestions(cards, Math.min(10, cards.length), 'mixed'), { title: 'Quiz: ' + t.name, classId: t.classId, kind: 'quiz' }); });
      $('[data-del]', r).onclick = async () => { if (await confirmBox(`Delete topic "${t.name}"? Cards and sessions stay; they just won’t be grouped under it.`)) { S.decks.forEach((d) => { if (d.topicId === t.id) delete d.topicId; }); S.cards.forEach((c) => { if (c.topicId === t.id) delete c.topicId; }); remove('topics', t.id); save('decks', 'cards'); close(); } };
    } });
}

// ---------- workload ----------
function intelWorkload() {
  const t = today(), days = Array.from({ length: 14 }, (_, i) => addDays(t, i)), bp = balancePlan(14), er = estRatio(), cap = workCap();
  const byDue = days.map((d) => ({ label: fmtDay(d), short: d === t ? 'Today' : DAYS[dow(d)].slice(0, 2) + ' ' + +d.slice(8), today: d === t, parts: S.classes.map((c) => ({ name: c.name, color: c.color, v: sum(openAssignments().filter((a) => a.classId === c.id && (a.due === d || (d === t && a.due < t))).map(remainingMins)) })), mark: majorDeadlines(d, 0).length ? majorDeadlines(d, 0).map((x) => esc(x.title)).join('<br>') : '' }));
  const balanced = bp.alloc.map((d) => ({ label: fmtDay(d.date), short: d.date === t ? 'Today' : DAYS[dow(d.date)].slice(0, 2) + ' ' + +d.date.slice(8), today: d.date === t, parts: S.classes.map((c) => ({ name: c.name, color: c.color, v: sum(d.items.filter((x) => x.a.classId === c.id).map((x) => x.mins)) })) }));
  const wl = weeklyLoad(8), nz = wl.map((w) => w.total).filter(Boolean).sort((a, b) => a - b), med = nz.length ? nz[Math.floor(nz.length / 2)] : 0, cl = deadlineClusters();
  const open = openAssignments().filter((a) => a.due).sort((a, b) => a.due.localeCompare(b.due));
  return { sub: `Work capacity ${fmtMins(cap)}/day · estimates ${er.measured ? `adjusted ×${round(er.r, 2)} from your logged times (${er.n} assignments)` : 'use your entries (log actual minutes on 3+ assignments to calibrate)'}`,
    html: `<div class="kpis">${kpi('calendar-clock', 'Due this week', fmtMins(wl[0].asg), `${openAssignments().filter((a) => a.due >= weekStart(t) && a.due <= addDays(weekStart(t), 6)).length} assignments, remaining time`)}${kpi('calendar-days', 'Next week', fmtMins(wl[1].total), `${wl[1].majors} major deadline${wl[1].majors === 1 ? '' : 's'}`)}${kpi('triangle-alert', 'Won’t fit', bp.late.length, bp.late.length ? 'at current capacity' : 'everything fits', bp.late.length ? 'var(--bad)' : 'var(--good)')}${kpi('layers', 'Deadline clusters', cl.length, '2+ majors within 3 days', cl.length ? 'var(--warn)' : null)}</div>
      ${cl.map((c) => `<div class="alert warn"><span class="ai">${icon('calendar-clock', 15)}</span><span><b>${c.items.length} major deadlines between ${fmtDay(c.start)} and ${fmtDay(c.end)}</b><br><span class="small muted">${c.items.map((x) => `${esc(x.title)} (${esc(clsName(x.classId))}, ${fmtDate(x.date)})`).join(' · ')}</span></span></div>`).join('')}
      <div class="grid g-12"><div class="card s-6"><div class="card-h"><h3>If you work on the due date</h3><span class="end tiny muted">remaining work by due day</span></div>${stackBars(byDue, { cap, capLabel: `${fmtMins(cap)} capacity`, fmt: fmtMins, fmtAxis: (v) => Math.round(v / 60) + 'h', empty: 'Nothing due in the next 14 days.' })}<p class="tiny dim" style="margin:4px 0 0">Red dots mark major deadlines. Overdue work is counted in Today.</p></div>
        <div class="card s-6"><div class="card-h"><h3>Balanced plan</h3>${tagEst}<span class="end tiny muted">earliest deadline first</span></div>${stackBars(balanced, { cap, capLabel: 'capacity', fmt: fmtMins, fmtAxis: (v) => Math.round(v / 60) + 'h', empty: 'Nothing to spread.' })}${bp.late.length ? `<div class="alert bad" style="margin-top:8px"><span class="ai">${icon('triangle-alert', 14)}</span><span class="small">Won’t finish in time at ${fmtMins(cap)}/day: ${bp.late.map((x) => `${esc(x.a.title)} (short ${fmtMins(x.short)})`).join(', ')}.</span></div>` : ''}</div>
        <div class="card s-5"><div class="card-h"><h3>Do today to stay balanced</h3></div>${bp.alloc[0].items.length ? `<div class="list">${bp.alloc[0].items.map((x) => `<div class="li click" data-aid="${x.a.id}"><span class="cbar" style="--c:${clsColor(x.a.classId)}"></span><span class="grow"><span class="t">${esc(x.a.title)}</span><div class="s">due ${relDayL(x.a.due)} · ${fmtMins(remainingMins(x.a))} left in total</div></span><b class="num">${fmtMins(x.mins)}</b></div>`).join('')}</div>` : '<p class="small muted">Nothing needs to be started today.</p>'}<p class="tiny dim" style="margin:8px 0 0">Change your daily work capacity in Settings.</p></div>
        <div class="card s-7"><div class="card-h"><h3>Weekly load</h3><span class="end tiny muted">assignments + exam prep · median ${fmtMins(med)}</span></div>${stackBars(wl.map((w, i) => ({ label: 'Week of ' + fmtDate(w.from), short: i === 0 ? 'This wk' : fmtDate(w.from, { month: 'numeric', day: 'numeric' }), today: i === 0, parts: [{ name: 'Assignments', color: 'var(--accent)', v: w.asg }, { name: 'Exam prep', color: 'var(--accent-2)', v: w.prep }], mark: w.total > med * 1.5 && w.total >= 240 && nz.length >= 2 ? `Busy: ${fmtMins(w.total)} vs typical ${fmtMins(med)}` : '' })), { fmt: fmtMins, fmtAxis: (v) => Math.round(v / 60) + 'h', empty: 'No upcoming work.' })}<div class="legend"><span><i class="dot-c"></i>Assignments</span><span><i class="dot-c" style="--c:var(--accent-2)"></i>Exam prep</span><span><i class="dot-c" style="--c:var(--bad)"></i>Unusually busy (1.5× median)</span></div></div>
        <div class="card s-12"><div class="card-h"><h3>Open assignments</h3><span class="end tiny muted">click to break into steps</span></div>${open.length ? `<div class="table-wrap"><table class="table"><thead><tr><th>Assignment</th><th>Due</th><th>Difficulty</th><th>Time left</th><th>Progress</th><th>Deadline risk</th><th>Priority</th></tr></thead><tbody>${open.map((a) => { const df = difficultyOf(a), dr = deadlineRisk(a), st = a.steps || [], p = priorityOf(a); return `<tr class="click-row" data-aid="${a.id}"><td><span class="row"><i class="dot-c" style="--c:${clsColor(a.classId)}"></i><b style="font-weight:600">${esc(a.title)}</b></span><div class="tiny muted">${esc(clsName(a.classId))} · ${TYPES[a.type]}</div></td><td class="small ${effStatus(a) === 'overdue' ? 'bad' : ''}" style="white-space:nowrap">${relDay(a.due)}</td><td><span class="badge ${df.level === 3 ? 'bad' : df.level === 2 ? 'warn' : 'good'}" title="${esc(df.src)}">${df.label}</span></td><td class="num small">${fmtMins(remainingMins(a))}</td><td style="min-width:110px">${st.length ? `<div class="bar"><i style="width:${(st.filter((s) => s.done).length / st.length) * 100}%"></i></div><span class="tiny muted">${st.filter((s) => s.done).length}/${st.length} steps</span>` : `<span class="tiny dim">${STATUS[effStatus(a)][0]}</span>`}</td><td>${dr ? `<span class="badge ${dr.level === 'overdue' || dr.level === 'high' ? 'bad' : dr.level === 'tight' ? 'warn' : 'good'}">${{ overdue: 'Overdue', high: 'Won’t fit', tight: 'Tight', ok: 'On track' }[dr.level]}</span>` : ''}</td><td class="num"><b>${p.score}</b></td></tr>`; }).join('')}</tbody></table></div>` : emptyState('circle-check', 'No open assignments', '')}</div></div>`,
    };
}
